examples.template:
FlowRow(
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    itemVerticalAlignment = Alignment.CenterVertically,
) {
    MonarchAiConfidenceMeter(
        value = {{meters.0.value|double}}f,
        icon = { level ->
            MonarchIcon(
                when (level) {
                    MonarchAiConfidenceLevel.Low -> SampleIcons.Warning
                    MonarchAiConfidenceLevel.Medium -> SampleIcons.Partial
                    MonarchAiConfidenceLevel.High -> SampleIcons.Success
                },
                contentDescription = null,
            )
        },
    )
    MonarchAiConfidenceMeter(
        value = {{meters.1.value|double}}f,
        icon = { level ->
            MonarchIcon(
                when (level) {
                    MonarchAiConfidenceLevel.Low -> SampleIcons.Warning
                    MonarchAiConfidenceLevel.Medium -> SampleIcons.Partial
                    MonarchAiConfidenceLevel.High -> SampleIcons.Success
                },
                contentDescription = null,
            )
        },
    )
    MonarchAiConfidenceMeter(
        value = {{meters.2.value|double}}f,
        showValue = {{meters.2.showValue}},
        icon = { level ->
            MonarchIcon(
                when (level) {
                    MonarchAiConfidenceLevel.Low -> SampleIcons.Warning
                    MonarchAiConfidenceLevel.Medium -> SampleIcons.Partial
                    MonarchAiConfidenceLevel.High -> SampleIcons.Success
                },
                contentDescription = null,
            )
        },
    )
}

